xml.Script:
        clBlue    := '0000C8';
        clGreen   := '009600';
        clRed     := 'C80000';
        clYellow  := 'FFFF00';
        clWhite   := 'FFFFFF';

        R := 0.5;

        H := R * sqrt(6) / 2;
        sAngle := PI * 2 / 3;
        for i := 0 to 2 do begin
            x[i] := R * sin(sAngle * i);
            y[i] := R * cos(sAngle * i);
        end;

        da := sAngle / 4;
        for i := 0 to 2 do begin
            ax[i] := sin(sAngle * i + da);
            ay[i] := cos(sAngle * i + da);
        end;
        az := sqrt(2) / 2;
